question:
Find the output from the following: take input and looks the output: Suppose
Input: 6789
Output: 9876
#include <stdio.h>
int main()
{
    int number, rev = 0, remainder;
    printf("
Enter a number: ");
    scanf("%d",&number);
    printf("
Reversed Number: ");
    while(number != 0)
    {
        remainder = number%10;
        rev = rev*10 + remainder;
        number /= 10;
    }
    printf("%d",rev);
    return 0;
}
